# build_leon.py — series anuales de población, hogares y vivienda para León (provincia y capital).
# Entrada: respuestas JSON de la API del INE (servicios.ine.es/wstempus) y Excel del Ministerio de Vivienda
# (apps.fomento.gob.es/BoletinOnline2/sedal/*.XLS), descargados sin modificar en <base>/ine y <base>/mivau_dl.
# Uso: python build_leon.py <base> <salida>
import json, os, re, sys, collections
import xlrd, openpyxl

BASE, OUT = sys.argv[1], sys.argv[2]
INE = os.path.join(BASE, 'ine')
MIV = os.path.join(BASE, 'mivau_dl')
CODE = open(os.path.abspath(__file__), encoding='utf-8').read()


def ine(fname):
    return json.load(open(os.path.join(INE, fname), encoding='utf-8'))


def series(fname, pattern):
    """Devuelve {(año, periodo): valor} de la primera serie del INE cuyo nombre casa con pattern."""
    rx = re.compile(pattern)
    for s in ine(fname):
        if rx.search(s['Nombre']):
            return {(p['Anyo'], p.get('FK_Periodo')): p['Valor'] for p in s['Data'] if p['Valor'] is not None}
    raise KeyError(pattern)


def annual(d):  # una observación por año
    return {y: v for (y, _), v in d.items()}


def jan(d):  # observación a 1 de enero (periodo 19 en la Estadística Continua de Población)
    return {y: v for (y, p), v in d.items() if p == 19}


def monthly_sum(d):  # suma de 12 meses; años incompletos se descartan
    s, n = collections.Counter(), collections.Counter()
    for (y, p), v in d.items():
        s[y] += v; n[y] += 1
    return {y: s[y] for y in s if n[y] == 12}


def monthly_mean(d):
    s, n = collections.Counter(), collections.Counter()
    for (y, p), v in d.items():
        s[y] += v; n[y] += 1
    return {y: s[y] / n[y] for y in s if n[y] == 12}


# ---------- Ministerio de Vivienda (Excel) ----------
def xls_row_by_year(fname, label, year_row, first_col=2):
    """Tablas con una fila por provincia y una columna por año (series anuales)."""
    sh = xlrd.open_workbook(os.path.join(MIV, fname)).sheet_by_index(0)
    years = {}
    for c, v in enumerate(sh.row_values(year_row)):
        if c >= 1 and re.match(r'^\s*(19|20)\d\d(\.0)?\s*$', str(v)):
            years[c] = int(float(v))
    for r in range(sh.nrows):
        row = sh.row_values(r)
        if str(row[1]).strip() == label or str(row[0]).strip() == label:
            return {y: row[c] for c, y in years.items() if isinstance(row[c], float)}
    raise KeyError(label)


def xls_quarterly_annual(fname, label, label_cols=(0, 1), agg='sum', want_rows=1):
    """Tablas trimestrales repartidas en varias hojas, con cabecera 'Año XXXX' sobre bloques de 4 columnas."""
    wb = xlrd.open_workbook(os.path.join(MIV, fname))
    vals = collections.defaultdict(dict)
    for sh in wb.sheets():
        hdr = None
        for r in range(min(sh.nrows, 20)):
            row = sh.row_values(r)
            ys = [c for c, v in enumerate(row) if re.match(r'^\s*(Año\s*)?(19|20)\d\d', str(v))]
            if len(ys) >= 2:
                hdr = r; break
        if hdr is None:
            continue
        col_year, cur = {}, None
        for c, v in enumerate(sh.row_values(hdr)):
            m = re.search(r'((19|20)\d\d)', str(v))
            if m and c > 0:
                cur = int(m.group(1))
            if cur and c > 0:
                col_year[c] = cur
        qn = collections.Counter(); qidx = {}
        for c in sorted(col_year):
            qn[col_year[c]] += 1; qidx[c] = qn[col_year[c]]
        found = 0
        for r in range(hdr + 1, sh.nrows):
            row = sh.row_values(r)
            lab = ' '.join(str(row[c]).strip() for c in label_cols if str(row[c]).strip())
            if lab == label:
                found += 1
                if found < want_rows:
                    continue
                for c, y in col_year.items():
                    if isinstance(row[c], float) and qidx[c] <= 4:
                        vals[y][qidx[c]] = row[c]
                break
    out = {}
    for y, q in vals.items():
        if len(q) == 4:
            out[y] = sum(q.values()) if agg == 'sum' else sum(q.values()) / 4
    return out


def mun_quarterly_annual(fname, municipio):
    """Transacciones por municipio: una hoja, cabecera de años en la fila 10, trimestres consecutivos."""
    sh = xlrd.open_workbook(os.path.join(MIV, fname)).sheet_by_index(0)
    hdr = sh.row_values(10)
    col_year, cur = {}, None
    for c, v in enumerate(hdr):
        m = re.search(r'(20\d\d)', str(v))
        if m:
            cur = int(m.group(1))
        if cur:
            col_year[c] = cur
    for r in range(sh.nrows):
        row = sh.row_values(r)
        if any(str(row[c]).strip() == municipio for c in (0, 1)) and any(isinstance(row[c], float) for c in col_year):
            s, n = collections.Counter(), collections.Counter()
            for c, y in col_year.items():
                if isinstance(row[c], float):
                    s[y] += row[c]; n[y] += 1
            return {y: s[y] for y in s if n[y] == 4}
    raise KeyError(municipio)


def buyers_by_residence():
    """Compraventas en la provincia de León según residencia del comprador (tablas 1.6 y 1.6.2)."""
    wb = xlrd.open_workbook(os.path.join(MIV, '340101d0.xls'))
    res = collections.defaultdict(collections.Counter)
    for sh in wb.sheets():
        m = re.match(r'(\d)t\s*(\d{4})', sh.name.strip()); y = int(m.group(2))
        for r in range(sh.nrows):
            row = sh.row_values(r)
            if str(row[1]).strip() == 'León':
                for k, c in (('total', 3), ('residentes', 4), ('residentes_espanoles', 5), ('residentes_extranjeros', 6), ('no_residentes', 8)):
                    if isinstance(row[c], float):
                        res[y][k] += row[c]
                res[y]['q'] += 1
                break
    wb = xlrd.open_workbook(os.path.join(MIV, '340101f0.xls'))
    for sh in wb.sheets():
        m = re.match(r'(\d)t\s*(\d{4})', sh.name.strip())
        if not m:
            continue
        y = int(m.group(2)); h2 = h1 = None
        for r in range(10, 20):
            row = [str(x).strip() for x in sh.row_values(r)]
            if 'Almería' in row:
                h2 = row; h1 = [str(x).strip() for x in sh.row_values(r - 1)]; break
        if not h2:
            continue
        names = {c: (h2[c] or h1[c]) for c in range(4, len(h2)) if (h2[c] or h1[c])}
        col_leon = [c for c, n in names.items() if n == 'León'][0]
        for r in range(sh.nrows):
            row = sh.row_values(r)
            if any(str(x).strip() == 'León' for x in row[:3]):
                res[y]['res_total_16_2'] += row[3]
                res[y]['compradores_leoneses'] += row[col_leon]
                for c, n in names.items():
                    if n in ('Madrid', 'Asturias') and isinstance(row[c], float):
                        res[y]['desde_' + n.lower()] += row[c]
                res[y]['q2'] += 1
                break
    out = {}
    for y, a in res.items():
        if a['q'] == 4 and a['q2'] == 4:
            out[y] = {
                'compradores_residentes': int(a['residentes']),
                'compradores_otra_provincia': int(a['res_total_16_2'] - a['compradores_leoneses']),
                'compradores_madrid': int(a['desde_madrid']),
                'compradores_asturias': int(a['desde_asturias']),
                'compradores_extranjeros_residentes': int(a['residentes_extranjeros']),
                'compradores_no_residentes': int(a['no_residentes']),
            }
    return out


def tasado_capital():
    """Valor tasado (€/m²) de León capital: media de los cuatro trimestres (tabla 4, una hoja por trimestre)."""
    wb = xlrd.open_workbook(os.path.join(MIV, '35103500.xls'))
    v = collections.defaultdict(list)
    for sh in wb.sheets():
        m = re.match(r'T(\d)A(\d{4})', sh.name.strip())
        if not m or int(m.group(2)) < 2010:
            continue
        for r in range(sh.nrows):
            row = sh.row_values(r)
            if str(row[2]).strip() == 'León' and isinstance(row[5], float):
                v[int(m.group(2))].append(row[5]); break
    return {y: sum(x) / len(x) for y, x in v.items() if len(x) == 4}


def parque():
    out = {}
    for fname in ('33100500.xlsx', '33102000.xlsx'):
        ws = openpyxl.load_workbook(os.path.join(MIV, fname), read_only=True, data_only=True).worksheets[0]
        rows = list(ws.iter_rows(values_only=True))
        years = [int(v) for v in rows[11] if isinstance(v, (int, float))]
        for row in rows:
            if row[1] and str(row[1]).strip() == 'León':
                nums = [v for v in row[2:] if isinstance(v, (int, float))]
                if fname.startswith('331005'):
                    for y, n in zip(years, nums):
                        out.setdefault(y, {})['viviendas_total'] = int(n)
                else:
                    for i, y in enumerate(years):
                        out.setdefault(y, {})['viviendas_principales'] = int(nums[3 * i + 1])
                        out[y]['viviendas_no_principales'] = int(nums[3 * i + 2])
                break
    return out


def write(name, rows, sources, notes=''):
    meta = [{'label': 'build_leon.py', 'value': CODE, 'type': 'code', 'lang': 'python'},
            {'label': 'Fuentes', 'value': sources}]
    if notes:
        meta.append({'label': 'Notas', 'value': notes})
    with open(os.path.join(OUT, name + '.json'), 'w', encoding='utf-8') as f:
        json.dump({'rows': rows, 'meta': meta}, f, ensure_ascii=False)


def rnd(v):
    return None if v is None else int(round(v))


os.makedirs(OUT, exist_ok=True)

# ---------- 1. Población ----------
pad_prov = annual(series('cache_2877_16_.json', r'^León\. Total\. Total habitantes'))
pad_cap = {}
for s in ine('cache_2877_16_.json'):
    if s['Nombre'].startswith('León. Total. Total habitantes'):
        pad_cap = {p['Anyo']: p['Valor'] for p in s['Data']}  # la segunda serie 'León.' es el municipio
ecp_tot = jan(series('cache_59591_100_tv=115_25.json', r'^León\. Todas las edades\. Total\. Total\.'))
ecp_esp = jan(series('cache_59591_100_tv=115_25.json', r'^León\. Todas las edades\. Española\. Total\.'))
ecp_ext = jan(series('cache_59591_100_tv=115_25.json', r'^León\. Todas las edades\. Extranjera\. Total\.'))
adrh = {}
for s in ine('adrh_leon.json'):
    if s['Nombre'].startswith('León. Población. Dato base'):
        adrh['pob'] = {p['Anyo']: p['Valor'] for p in s['Data']}
    if s['Nombre'].startswith('León. Porcentaje de población española'):
        adrh['esp'] = {p['Anyo']: p['Valor'] for p in s['Data']}
rows = []
for y in range(2010, 2027):
    ext_cap = None
    if y in adrh['pob'] and y in adrh['esp']:
        ext_cap = rnd(adrh['pob'][y] * (100 - adrh['esp'][y]) / 100)
    rows.append({'anio': y,
                 'pob_provincia_padron': rnd(pad_prov.get(y)), 'pob_capital_padron': rnd(pad_cap.get(y)),
                 'pob_provincia_ecp': rnd(ecp_tot.get(y)), 'espanoles_provincia': rnd(ecp_esp.get(y)),
                 'extranjeros_provincia': rnd(ecp_ext.get(y)), 'extranjeros_capital_aprox': ext_cap})
write('poblacion', rows,
      'INE Padrón municipal, tabla 2877 (a 1 de enero). INE Estadística Continua de Población, tabla 59591 (a 1 de enero). '
      'INE Atlas de Distribución de Renta de los Hogares, tabla 31078 (porcentaje de población española, León municipio).',
      'extranjeros_capital_aprox = población ADRH × (100 − % población española) / 100; el porcentaje viene redondeado a un decimal, '
      'así que el resultado tiene un margen de unas ±60 personas.')

# ---------- 2. Nacimientos, defunciones y migraciones ----------
nac = monthly_sum(series('cache_6524_200_.json', r'^León\.'))
dfn = monthly_sum(series('cache_6561_200_.json', r'^León\.'))
ext_old = annual(series('cache_24329_15_.json', r'^León\. Total\. Saldo con el extranjero'))
int_old = annual(series('cache_24385_15_.json', r'^León\. Saldo de migración interprovincial\. Total'))
emcr = {k: annual(series('cache_69764_12_.json', r'^León\. Todas las edades\. Total\. Total\. Saldo ' + k)) for k in ('total', 'exterior', 'interior')}
emcr_ext = annual(series('cache_69764_12_.json', r'^León\. Todas las edades\. Extranjera\. Total\. Saldo total'))
emcr_esp = annual(series('cache_69764_12_.json', r'^León\. Todas las edades\. Española\. Total\. Saldo total'))
cap = collections.defaultdict(dict)
seen = collections.Counter()
for s in ine('cache_69767_12_.json'):
    m = re.match(r'^León\. Ambos sexos\. Saldo (total|exterior|interior)', s['Nombre'])
    if m:
        seen[m.group(1)] += 1
        if seen[m.group(1)] == 2:  # la primera es la provincia, la segunda el municipio
            for p in s['Data']:
                cap[p['Anyo']][m.group(1)] = p['Valor']
rows = []
for y in range(2010, 2025):
    r = {'anio': y, 'nacimientos': rnd(nac.get(y)), 'defunciones': rnd(dfn.get(y))}
    r['saldo_natural'] = None if r['nacimientos'] is None or r['defunciones'] is None else r['nacimientos'] - r['defunciones']
    if y <= 2020:
        r['saldo_exterior'] = rnd(ext_old.get(y)); r['saldo_interior'] = rnd(int_old.get(y)); r['metodo'] = 'EM (hasta 2020)'
    else:
        r['saldo_exterior'] = rnd(emcr['exterior'].get(y)); r['saldo_interior'] = rnd(emcr['interior'].get(y)); r['metodo'] = 'EMCR (desde 2021)'
    r['saldo_migratorio'] = None if r['saldo_exterior'] is None else r['saldo_exterior'] + (r['saldo_interior'] or 0)
    r['saldo_migr_extranjeros'] = rnd(emcr_ext.get(y)); r['saldo_migr_espanoles'] = rnd(emcr_esp.get(y))
    c = cap.get(y, {})
    r['capital_saldo_migratorio'] = rnd(c.get('total')); r['capital_saldo_exterior'] = rnd(c.get('exterior')); r['capital_saldo_interior'] = rnd(c.get('interior'))
    rows.append(r)
write('movimientos', rows,
      'INE Movimiento Natural de la Población: nacimientos (tabla 6524) y defunciones (tabla 6561) por residencia, suma de 12 meses. '
      'INE Estadística de Migraciones (tablas 24329 y 24385, 2010–2020) y Estadística de Migraciones y Cambios de Residencia '
      '(tablas 69764 y 69767, desde 2021).',
      'En 2021 cambia la estadística de migraciones: las dos etapas no son del todo comparables. Saldo interior = con otras provincias '
      '(hasta 2020) o con otros municipios de España (desde 2021, y para la capital incluye mudanzas al alfoz).')

# ---------- 3. Hogares (Estadística Continua de Población, trimestral) ----------
ecp_h = {}
for s in ine('ecp60133.json'):
    m = re.match(r'^León\. (Total|1|2|3|4 y más)\. Hogares', s['Nombre'])
    if m:
        ecp_h[m.group(1)] = {p['Fecha'][:10]: p['Valor'] for p in s['Data']}
size = {}
for s in ine('ecp60134.json'):
    if s['Nombre'].startswith('León. Tamaño medio'):
        size = {p['Fecha'][:10]: p['Valor'] for p in s['Data']}
rows = []
for k in sorted(ecp_h['Total']):  # la fecha viene como texto 'AAAA-MM-DD' (1 de enero, abril, julio y octubre)
    rows.append({'fecha': k, 'hogares': rnd(ecp_h['Total'][k]),
                 'hogares_1': rnd(ecp_h['1'][k]), 'hogares_2': rnd(ecp_h['2'][k]), 'hogares_3': rnd(ecp_h['3'][k]),
                 'hogares_4_y_mas': rnd(ecp_h['4 y más'][k]), 'personas_por_hogar': size.get(k)})
write('hogares', rows, 'INE Estadística Continua de Población: hogares por tamaño (tabla 60133) y tamaño medio del hogar (tabla 60134), provincia de León.',
      'Hogares de personas que viven en viviendas familiares (no incluye residencias ni otros establecimientos colectivos).')

# ---------- 4. Viviendas: parque y obra nueva ----------
ini = xls_row_by_year('32200500.xls', 'León', 10)
ter = xls_row_by_year('32201000.xls', 'León', 10)
pq = parque()
rows = []
for y in range(2001, 2026):
    r = {'anio': y, 'viviendas_iniciadas': rnd(ini.get(y)), 'viviendas_terminadas': rnd(ter.get(y))}
    r.update(pq.get(y, {}))
    rows.append(r)
write('viviendas', rows,
      'Ministerio de Vivienda: viviendas libres iniciadas (tabla 3.1) y terminadas (tabla 3.2), a partir de visados y certificados de fin de obra '
      'de los colegios de aparejadores; estimación del parque de viviendas (tablas 1 y 2). Provincia de León.',
      'Iniciadas y terminadas son solo vivienda libre. Viviendas principales y no principales son una estimación del Ministerio, no un recuento.')

# ---------- 5. Compraventas, hipotecas y compradores ----------
mv_tot = xls_quarterly_annual('34010110.xls', 'León', want_rows=1)
mv_new = xls_quarterly_annual('34010180.xls', 'León', want_rows=1)
cap_tot = mun_quarterly_annual('34010210.xls', 'León')
cap_new = mun_quarterly_annual('34010240.xls', 'León')
alfoz = {y: mun_quarterly_annual('34010210.xls', 'San Andrés del Rabanedo')[y] + mun_quarterly_annual('34010210.xls', 'Villaquilambre')[y]
         for y in cap_tot}
etdp = annual(series('cache_6155_20_.json', r'^León\. General\. Compraventa'))
etdp_new = annual(series('cache_6155_20_.json', r'^León\. Vivienda nueva\. Compraventa'))
hip = monthly_sum(series('cache_76317_240_.json', r'^Viviendas\. Número de hipotecas\. León\.'))
hip_imp = monthly_sum(series('cache_76317_240_.json', r'^Viviendas\. Importe de hipotecas\. León\.'))
buy = buyers_by_residence()
rows = []
for y in range(2007, 2026):
    r = {'anio': y,
         'compraventas_notarios': rnd(mv_tot.get(y)), 'compraventas_nueva_notarios': rnd(mv_new.get(y)),
         'compraventas_registro': rnd(etdp.get(y)), 'compraventas_nueva_registro': rnd(etdp_new.get(y)),
         'hipotecas_vivienda': rnd(hip.get(y)), 'hipotecas_importe_miles': rnd(hip_imp.get(y)),
         'capital_compraventas': rnd(cap_tot.get(y)), 'capital_compraventas_nueva': rnd(cap_new.get(y)),
         'alfoz_compraventas': rnd(alfoz.get(y))}
    r.update(buy.get(y, {}))
    rows.append(r)
write('compraventas', rows,
      'Ministerio de Vivienda, transacciones inmobiliarias de vivienda (datos de notarios): tablas 1, 1.3, 1.6, 1.6.2, 2 y 2.3. '
      'INE Estadística de Transmisiones de Derechos de la Propiedad, tabla 6155 (compraventas inscritas en el registro). '
      'INE Estadística de Hipotecas, tabla 76317 (hipotecas constituidas sobre viviendas, suma de 12 meses; importe en miles de euros).',
      'Las cifras de notarios cuentan la firma de la escritura; las del registro, su inscripción semanas después, por eso no coinciden. '
      'Alfoz = San Andrés del Rabanedo + Villaquilambre. compradores_otra_provincia = compradores residentes en España que no viven en la provincia de León.')

# ---------- 6. Precios, IPC y renta ----------
tas_prov = xls_quarterly_annual('35101000.xls', 'León', agg='mean')
tas_esp = xls_quarterly_annual('35101000.xls', 'TOTAL NACIONAL', agg='mean')
tas_cap = tasado_capital()
ipc = monthly_mean(series('cache_24081_240_.json', r'^León\. Índice general'))
renta = annual(series('cache_31070_12_.json', r'^León\. Dato base\. Renta neta media por hogar'))
rows = []
for y in range(2007, 2026):
    rows.append({'anio': y, 'tasado_provincia': rnd(tas_prov.get(y)), 'tasado_capital': rnd(tas_cap.get(y)),
                 'tasado_espana': rnd(tas_esp.get(y)), 'ipc_leon_base2025': None if y not in ipc else round(ipc[y], 2),
                 'renta_media_hogar_capital': rnd(renta.get(y))})
write('precios', rows,
      'Ministerio de Vivienda: valor tasado medio de la vivienda libre (tabla 1, provincias; tabla 4, municipios de más de 25.000 habitantes), media de 4 trimestres. '
      'INE IPC, índice general de la provincia de León (tabla 24081, base 2025 = 100, media anual). '
      'INE Atlas de Distribución de Renta de los Hogares, tabla 31070 (renta neta media por hogar, León municipio).')

# ---------- 7. Viviendas de uso turístico ----------
vte_p = series('cache_39364_20_.json', r'^León\. Viviendas turísticas')
vte_c = {}
seen = 0
for s in ine('cache_39363_20_.json'):
    if s['Nombre'].startswith('León. Viviendas turísticas'):
        vte_c = {(p['Anyo'], p['FK_Periodo']): p['Valor'] for p in s['Data']}
mon = {2: '02', 5: '05', 8: '08', 11: '11'}
rows = [{'fecha': f'{y}-{mon[p]}-01', 'turisticas_provincia': rnd(v), 'turisticas_capital': rnd(vte_c.get((y, p)))}
        for (y, p), v in sorted(vte_p.items())]
write('turisticas', rows, 'INE Viviendas turísticas en España (experimental): tablas 39364 (provincia) y 39363 (municipio de León).',
      'Anuncios activos en plataformas de alquiler turístico, contados por el INE en febrero/agosto (hasta 2024) y mayo/noviembre (desde finales de 2024).')
print('ok', sorted(os.listdir(OUT)))
